-- Accommodation and business directory used by staff and Respond.io lookups.
CREATE TABLE IF NOT EXISTS public.accommodation_directory (
  id                  bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  name                text NOT NULL,
  aliases             text[] NOT NULL DEFAULT '{}',
  area                text NOT NULL,
  address             text,
  delivery_fee        numeric(10,2),
  collection_fee      numeric(10,2),
  is_partner          boolean NOT NULL DEFAULT false,
  delivery_available  boolean NOT NULL DEFAULT true,
  is_active           boolean NOT NULL DEFAULT true,
  created_at          timestamptz NOT NULL DEFAULT now(),
  updated_at          timestamptz NOT NULL DEFAULT now()
);

CREATE UNIQUE INDEX IF NOT EXISTS accommodation_directory_name_idx
  ON public.accommodation_directory (lower(trim(name)));
CREATE INDEX IF NOT EXISTS accommodation_directory_area_idx
  ON public.accommodation_directory (area) WHERE is_active;

DROP TRIGGER IF EXISTS accommodation_directory_updated_at ON public.accommodation_directory;
CREATE TRIGGER accommodation_directory_updated_at
  BEFORE UPDATE ON public.accommodation_directory
  FOR EACH ROW EXECUTE FUNCTION public.update_updated_at();

ALTER TABLE public.accommodation_directory ENABLE ROW LEVEL SECURITY;

DROP POLICY IF EXISTS accommodation_directory_read ON public.accommodation_directory;
CREATE POLICY accommodation_directory_read ON public.accommodation_directory
  FOR SELECT TO authenticated USING (true);

DROP POLICY IF EXISTS accommodation_directory_write ON public.accommodation_directory;
CREATE POLICY accommodation_directory_write ON public.accommodation_directory
  FOR ALL TO authenticated
  USING (public.has_permission('can_edit_settings'))
  WITH CHECK (public.has_permission('can_edit_settings'));

ON CONFLICT DO NOTHING;
